head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gJongcode = ""; // 업종코드
scwin.gUpjongJongmok = ""; // 업종에 따른 종목
scwin.gFilterType = ""; // "S":종목검색버튼,"O"
scwin.gJongName = ""; // 종목명
scwin.ssMarket = "N"; // 종목콤보확인
scwin.stat = "";
scwin.skw = "";
// bizspt/ULDSTF30302(IR처리) 화면에서 테스트
// TOBE : 회사명을 약어로 표시하기로 함(2026.05.29 이창민C)
//       상장구분에 따라 호출되게 수정(ASIS는 시장 콤보박스 바꾸면 상장구분 조회조건 수행X)
//       필터시에 oldComAbbrv 사용안하고 회사명으로만 검색되도록 수정(2026.06.05 이창민C)

scwin.tpcd = $c.stf.getUserInfo($p, "market"); // 세션의 시장구분

///////// 2. 초기화 영역 /////////
scwin.onpageload = function () {
    try {
        scwin.tpcd = "9"; // 현재 세션은 1이라서 임시로 9로 SET
        scwin.code1Sync();
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.onpageload" });
    }
};

scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.grd_jongmok_onkeydown = function (e) {
    try {
        if (e.keyCode === "13") {
            scwin.Confirm();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.grd_jongmok_onkeydown" });
    }
};

scwin.grd_jongmok_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.Confirm();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.grd_jongmok_oncelldblclick" });
    }
};

scwin.btn_Search_onclick = function () {
    try {
        scwin.JongmokName(ibx_jongmokName.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.btn_Search_onclick" });
    }
};

scwin.ibx_jongmokName_onkeydown = function () {
    try {
        if (window.event.keyCode === "13") {
            scwin.JongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.ibx_jongmokName_onkeydown" });
    }
};

