        scwin.Jongmok('0', '9');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.btn_num_onclick" });
    }
};

scwin.sbx_market_onchange = function (info) {
    try {
        if (scwin.ssMarket === "Y") {
            ibx_jongmokName.setValue("");
            scwin.tpcd = info.newValue;
            scwin.stat = sbx_stat.getValue();

            // TOBE : 상장구분에 따라 호출되게 수정
            if (scwin.stat === '0') {
                scwin.stat = "";
                scwin.listSync();
            } else {
                scwin.listSync2();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.sbx_market_onchange" });
    }
};

scwin.sbx_stat_onchange = function (info) {
	try {
		ibx_jongmokName.setValue("");
	    scwin.stat = info.newValue;

	    if (scwin.stat === '0') {
	        scwin.stat = "";
	        scwin.listSync();
	    } else {
	        scwin.listSync2();
	    }
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.sbx_stat_onchange" });
	}
};

scwin.dlt_jongmok_OnFilter = function () {
    try {
        dlt_jongmok.removeColumnFilterAll();

        if (scwin.skw !== "") {
            dlt_jongmok.setColumnFilter({ type: "row", colIndex: "comAbbrv", key: scwin.skw, condition: "and", exactMatch: false });
            // dlt_jongmok.setColumnFilter({ type: "row", colIndex: "oldComAbbrv", key: scwin.skw, condition: "or", exactMatch: false });
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007_KOSDAQ_IR.dlt_jongmok_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.sbm_jongmok_submitdone = function (e) {
    grd_jongmok.setFocusedCell(0, 0);
};

scwin.sbm_code1_submitdone = function (e) {
    scwin.marketSetCombo();
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.listSync = function () {
    let url = "/api/discls/common/popup/select-list-isur-cd-ir-value?mktTpCd=" + scwin.tpcd;

    $c.sbm.setAction(sbm_jongmok, url)
    $c.sbm.execute(sbm_jongmok);
};

scwin.listSync2 = function () {
    let url = "/api/discls/common/popup/select-list-isur-cd-ir-value?mktTpCd=" + scwin.tpcd + "&listStatCd=" + scwin.stat;

    $c.sbm.setAction(sbm_jongmok, url)
    $c.sbm.execute(sbm_jongmok);
};

/********************************************** 
 * 함수명   : Jongmok()
 * 설명     : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function (prevval, nextval) {
    ibx_jongmokName.setValue("");
    scwin.skw = "";
    scwin.dlt_jongmok_OnFilter();

    dlt_jongmok.sort("comAbbrv", 0);

    let cnt = 0;
    for (let i = 0; i < dlt_jongmok.getRowCount(); i++) {
        const name = dlt_jongmok.getCellData(i, "comAbbrv").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }

    grd_jongmok.setFocusedCell(cnt + 10, 0);
    grd_jongmok.setFocusedCell(cnt, 0);
};

/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function (keyCode) {
    /* TOBE : 다시 필터되면 필요없는 기능이라 주석처리
    var cnt = 0;
    var len = ibx_jongmokName.getValue().length;
    var txtVal = ibx_jongmokName.getValue().toUpperCase();

    dlt_jongmok.sort("comAbbrv", 0);

    for (let i = 0; i < dlt_jongmok.getTotalRow(); i++) {
        var name = dlt_jongmok.getCellData(i, "comAbbrv").substring(0, len).toUpperCase();
        if (txtVal == name) {
            cnt = i;
            break;
        }
    }

    if (cnt == 0) {
        dlt_jongmok.sort("comNm", 0);
        for (i = 0; i < dlt_jongmok.getTotalRow(); i++) {
            var name = dlt_jongmok.getCellData(i, "comNm").substring(0, len).toUpperCase();
            if (txtVal == name) {
                cnt = i;
                break;
            }
        }

    }    

    grd_jongmok.setFocusedCell(cnt + 10, 0);
    grd_jongmok.setFocusedCell(cnt, 0);
    */

    scwin.dlt_jongmok_OnFilter();
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokSearch = function () {
    scwin.skw = ibx_jongmokName.getValue();

    scwin.dlt_jongmok_OnFilter();
    grd_jongmok.setFocusedCell(0, 0)
};

/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function () {
    let pJongCode = dlt_jongmok.getCellData(dlt_jongmok.getRowPosition(), "isurCd");
    let pJongNm = dlt_jongmok.getCellData(dlt_jongmok.getRowPosition(), "comAbbrv");

    $c.cm.isurSearch_Rtn(pJongCode, pJongNm);
    await $c.win.closePopup();
};

scwin.code1Sync = function () {
    let url = "/api/discls/common/code/select-list-code-value?type=R&cdEngNm=SPOT_ISU_TRD_MKT_TP_CD";
    $c.sbm.setAction(sbm_code1, url);
    $c.sbm.execute(sbm_code1);
};

scwin.marketSetCombo = function () {
    if (scwin.tpcd !== "") {
        sbx_market.setValue(scwin.tpcd);
    }

    if (scwin.tpcd === "1" || scwin.tpcd === "2" || scwin.tpcd === "6") {
        sbx_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};

scwin.spotIsuTrdMktTpCdExp = function (data, formattedData, rowIdx, colIdx) {
    let listStatCd = dlt_jongmok.getCellData(rowIdx, "listStatCd");

    if (listStatCd === "Y") {
        grd_jongmok.setCellColor(rowIdx, "spotIsuTrdMktTpCd", "#000000");
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#000000");
        grd_jongmok.setCellColor(rowIdx, "isurCd", "#000000");
    } else if (listStatCd === "D") {
        grd_jongmok.setCellColor(rowIdx, "spotIsuTrdMktTpCd", "#FF0033");
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#FF0033");
        grd_jongmok.setCellColor(rowIdx, "isurCd", "#FF0033");
    } else if (listStatCd === "N") {
        grd_jongmok.setCellColor(rowIdx, "spotIsuTrdMktTpCd", "#009933");
        grd_jongmok.setCellColor(rowIdx, "comAbbrv", "#009933");
        grd_jongmok.setCellColor(rowIdx, "isurCd", "#009933");
    }

    return formattedData;
};
